// Importing necessary modules and components
import React, { useState, useEffect } from 'react';
import axios from 'axios';

// Importing the hero.css file as a JavaScript object
import styles from '..//hero.module.css';

// Defining constants for the API key and base URL
const apiKey = '499d99db6ce23991d21afde0deede0f1';
const baseUrl = 'https://api.themoviedb.org/3';

// Defining the HeroSection component
function HeroSection() {
 // Setting up state for the background image, movie title, movie overview, and release date
 const [bgImage, setBgImage] = useState(null);
 const [movieTitle, setMovieTitle] = useState(null);
 const [movieOverview, setMovieOverview] = useState(null);
 const [releaseDate, setReleaseDate] = useState(null);

 // Defining a function to fetch a random popular movie from the TMDB API
 const fetchRandomMovie = async () => {
   // Fetching the popular movies from the TMDB API
   const response = await axios.get(`${baseUrl}/discover/movie`, {
     params: {
       api_key: apiKey,
       sort_by: 'popularity.desc',
     },
   });

   // Getting the results array from the response
   const results = response.data.results;

   // Picking a random index from the results array
   const randomIndex = Math.floor(Math.random() * results.length);

   // Getting the poster_path, title, overview, and release_date of the random movie
   const posterPath = results[randomIndex].poster_path;
   const title = results[randomIndex].title;
   const overview = results[randomIndex].overview;
   const releaseDate = results[randomIndex].release_date;

   // Setting the state with the movie properties
   setBgImage(`https://image.tmdb.org/t/p/original${posterPath}`);
   setMovieTitle(title);
   setMovieOverview(overview);
   setReleaseDate(releaseDate);
 };

 // Using an effect hook to fetch a random movie when the component mounts
 useEffect(() => {
   fetchRandomMovie();
 }, []);

 // Rendering the hero section with the hero content
 return (
   // Using the styles object to access the CSS classes
   <div className={styles.HeroSection} style={{ backgroundImage: `url(${bgImage})` }}>
     <div className={styles.HeroContent}>
       <h1>{movieTitle}</h1>
       <h2>{movieOverview}</h2>
       <h3>Release date: {releaseDate}</h3>
       <button>Watch now</button>
     </div>
   </div>
 );
}

export default HeroSection;
